<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<div class="row justify-content-center"><div class="col-xl-10"><div class="card shadow-sm"><div class="card-body"><?php if($form_error):?><div class="alert alert-danger"><?=html_escape($form_error)?></div><?php endif;?><?php if(!$projects):?><div class="alert alert-warning">Create an active Project Master record before adding a BOQ.</div><?php endif;?><?=validation_errors('<div class="alert alert-danger">','</div>')?><?=form_open(current_url())?><div class="row g-3"><div class="col-md-4"><label class="form-label">Project *</label><select class="form-select" name="project_id" required><option value="">Select…</option><?php foreach($projects as$p):?><option value="<?=$p->option_id?>" <?=set_select('project_id',(string)$p->option_id,(string)set_value('project_id',$boq->project_id??'')===(string)$p->option_id)?>><?=html_escape($p->option_label)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">BOQ code *</label><input class="form-control text-uppercase" name="boq_code" maxlength="50" required value="<?=set_value('boq_code',$boq->boq_code??'')?>"></div><div class="col-md-5"><label class="form-label">BOQ name *</label><input class="form-control" name="boq_name" maxlength="255" required value="<?=set_value('boq_name',$boq->boq_name??'')?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3"><?=set_value('description',$boq->description??'')?></textarea></div><div class="col-md-5"><label class="form-label">Document reference</label><input class="form-control" name="document_reference" maxlength="255" value="<?=set_value('document_reference',$boq->document_reference??'')?>"></div><div class="col-md-2"><label class="form-label">Currency *</label><input class="form-control text-uppercase" name="currency_code" maxlength="3" required value="<?=set_value('currency_code',$boq->currency_code??'PHP')?>"></div><div class="col-md-2"><label class="form-label">Revision</label><input class="form-control" name="revision_no" maxlength="20" value="<?=set_value('revision_no',$boq->revision_no??'')?>"></div><div class="col-md-3"><label class="form-label">Status *</label><select class="form-select" name="boq_status"><?php foreach(array('DRAFT','VALIDATED','ACTIVE','ARCHIVED')as$s):?><option <?=set_select('boq_status',$s,set_value('boq_status',$boq->boq_status??'DRAFT')===$s)?>><?=$s?></option><?php endforeach;?></select></div></div><?php $active=$this->input->method(TRUE)!=='POST'&&($boq===NULL||$boq->is_active);?><div class="form-check my-4"><input class="form-check-input" type="checkbox" name="is_active" value="1" id="is_active" <?=set_checkbox('is_active','1',$active)?>><label class="form-check-label" for="is_active">Active</label></div><button class="btn btn-primary" <?=$projects?'':'disabled'?>>Save BOQ</button> <a class="btn btn-outline-secondary" href="<?=$boq?site_url('boq/'.$boq->boq_id):site_url('boq')?>">Cancel</a><?=form_close()?></div></div></div></div>
